package com.rpis.backend.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One appendix of the Terminal Report (for example "Appendix 1. Production-Index
 * Computation and Interpretation Notes" of the official format).
 *
 * <p>The appendix number is generated by the document renderer from the order of the
 * appendices, so the proponent only writes the title and the text.</p>
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class TerminalReportAppendix {

    private String title;
    private String text;

    /** True when the appendix carries a title or text. */
    public boolean hasContent() {
        return (title != null && !title.isBlank()) || (text != null && !text.isBlank());
    }
}
